private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true;
    }

    V firstVertex = vertices.iterator().next();
    Set<V> remainingVertices = new HashSet<>(vertices);
    remainingVertices.remove(firstVertex);

    for (V vertex : remainingVertices) {
        if (!graph.containsEdge(firstVertex, vertex)) {
            return false;
        }
    }

    return true;
}

